class Solution {
public:
    vector<int> gridIllumination(int n, vector<vector<int>>& lamps, vector<vector<int>>& queries) {
        unordered_set<long long> active;
        unordered_map<int, int> row_cnt, col_cnt, diag1_cnt, diag2_cnt;

        auto encode = [&](int r, int c) -> long long {
            return ((long long)r << 32) | (unsigned int)c;
        };

        for (const auto& lamp : lamps) {
            int r = lamp[0], c = lamp[1];
            long long code = encode(r, c);
            if (active.find(code) == active.end()) {
                active.insert(code);
                row_cnt[r]++;
                col_cnt[c]++;
                diag1_cnt[r - c]++;
                diag2_cnt[r + c]++;
            }
        }

        vector<int> ans;
        ans.reserve(queries.size());

        for (const auto& q : queries) {
            int r = q[0], c = q[1];
            if (row_cnt[r] > 0 || col_cnt[c] > 0 || diag1_cnt[r - c] > 0 || diag2_cnt[r + c] > 0) {
                ans.push_back(1);
            } else {
                ans.push_back(0);
            }

            for (int dr = -1; dr <= 1; ++dr) {
                for (int dc = -1; dc <= 1; ++dc) {
                    int nr = r + dr, nc = c + dc;
                    long long code = encode(nr, nc);
                    if (active.erase(code)) {
                        row_cnt[nr]--;
                        col_cnt[nc]--;
                        diag1_cnt[nr - nc]--;
                        diag2_cnt[nr + nc]--;
                    }
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int[] gridIllumination(int n, int[][] lamps, int[][] queries) {
        Set<Long> active = new HashSet<>();
        Map<Integer, Integer> rowCnt = new HashMap<>();
        Map<Integer, Integer> colCnt = new HashMap<>();
        Map<Integer, Integer> diag1Cnt = new HashMap<>();
        Map<Integer, Integer> diag2Cnt = new HashMap<>();

        for (int[] lamp : lamps) {
            int r = lamp[0], c = lamp[1];
            long code = (((long) r) << 32) | (c & 0xFFFFFFFFL);
            if (active.add(code)) {
                rowCnt.put(r, rowCnt.getOrDefault(r, 0) + 1);
                colCnt.put(c, colCnt.getOrDefault(c, 0) + 1);
                diag1Cnt.put(r - c, diag1Cnt.getOrDefault(r - c, 0) + 1);
                diag2Cnt.put(r + c, diag2Cnt.getOrDefault(r + c, 0) + 1);
            }
        }

        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; ++i) {
            int r = queries[i][0], c = queries[i][1];
            if (rowCnt.getOrDefault(r, 0) > 0 || colCnt.getOrDefault(c, 0) > 0 ||
                diag1Cnt.getOrDefault(r - c, 0) > 0 || diag2Cnt.getOrDefault(r + c, 0) > 0) {
                ans[i] = 1;
            } else {
                ans[i] = 0;
            }

            for (int dr = -1; dr <= 1; ++dr) {
                for (int dc = -1; dc <= 1; ++dc) {
                    int nr = r + dr, nc = c + dc;
                    long code = (((long) nr) << 32) | (nc & 0xFFFFFFFFL);
                    if (active.remove(code)) {
                        rowCnt.put(nr, rowCnt.get(nr) - 1);
                        colCnt.put(nc, colCnt.get(nc) - 1);
                        diag1Cnt.put(nr - nc, diag1Cnt.get(nr - nc) - 1);
                        diag2Cnt.put(nr + nc, diag2Cnt.get(nr + nc) - 1);
                    }
                }
            }
        }
        return ans;
    }
}

var gridIllumination = function(n, lamps, queries) {
    const active = new Set();
    const rowCnt = new Map();
    const colCnt = new Map();
    const diag1Cnt = new Map();
    const diag2Cnt = new Map();

    const inc = (map, key) => map.set(key, (map.get(key) || 0) + 1);
    const dec = (map, key) => map.set(key, (map.get(key) || 0) - 1);

    for (const [r, c] of lamps) {
        const key = `${r},${c}`;
        if (!active.has(key)) {
            active.add(key);
            inc(rowCnt, r);
            inc(colCnt, c);
            inc(diag1Cnt, r - c);
            inc(diag2Cnt, r + c);
        }
    }

    const ans = [];
    for (const [r, c] of queries) {
        if ((rowCnt.get(r) || 0) > 0 || (colCnt.get(c) || 0) > 0 ||
            (diag1Cnt.get(r - c) || 0) > 0 || (diag2Cnt.get(r + c) || 0) > 0) {
            ans.push(1);
        } else {
            ans.push(0);
        }

        for (let dr = -1; dr <= 1; dr++) {
            for (let dc = -1; dc <= 1; dc++) {
                const nr = r + dr, nc = c + dc;
                const key = `${nr},${nc}`;
                if (active.has(key)) {
                    active.delete(key);
                    dec(rowCnt, nr);
                    dec(colCnt, nc);
                    dec(diag1Cnt, nr - nc);
                    dec(diag2Cnt, nr + nc);
                }
            }
        }
    }
    return ans;
};
